INSERT INTO raw.youth_policy ("plcyNo", "plcyNm", "plcyKywdNm", "plcyExplnCn", "lclsfNm", "mclsfNm", "pvsnInstGroupCd", "plcyPvsnMthdCd", "plcySprtCn", "sprvsnInstCd", "sprvsnInstCdNm", "operInstCd", "operInstCdNm", "aplyYmd", "aplyPrdSeCd", "bizPrdSeCd", "bizPrdBgngYmd", "bizPrdEndYmd", "bizPrdEtcCn", "plcyAplyMthdCn", "aplyUrlAddr", "sbmsnDcmntCn", "srngMthdCn", "etcMttrCn", "refUrlAddr1", "refUrlAddr2", "sprtTrgtMinAge", "sprtTrgtMaxAge", "sprtTrgtAgeLmtYn", "mrgSttsCd", "earnCndSeCd", "earnMinAmt", "earnMaxAmt", "earnEtcCn", "addAplyQlfcCndCn", "ptcpPrpTrgtCn", "zipCd", "plcyMajorCd", "jobCd", "schoolCd", "sbizCd", "frstRegDt", "lastMdfcnDt", "plcyAprvSttsCd", "source_url", "raw_data") VALUES ('20260528005400113226', '(문체부) 청년예술인 예술활동 적립계좌', '보조금', '청년예술인에게 중장기 자산형성의 기회를 마련하여 안정적인 예술활동을 지원하는 사업', '금융･복지･문화', '예술인지원', '0054001', '0042006', '매월 일정 금액을 24개월간 적금 저축 시 가입자가 저축한 금액만큼 정부지원금을 지원 (1인 최대 240만원)
- 상품종류: 10만원 정액 적금
- 가입기간: 2년 (24개월)
- 납입한도: 월 10만원 (2년 최대 240만원)
- 지급방식: 만기 일시지급 (지원금은 만기 익월 지급)', '1371000', '문화체육관광부', '       ', NULL, NULL, '0057002', '0056001', '20260101', '20261231', NULL, '1. 예술활동증명확인
예술인경력정보시스템(https://www.kawfartist.kr)을 접속하시어
경력지원 > 예술활동증명 > 신청내역 진행 상태에서 신청일 현재 예술활동증명 유효 여부를 확인합니다.

2. 구비서류 확인
상품 및 구비서류를 확인하여 준비합니다.

3. 온라인 신청
공지사항에 공지된 신청기간 내 적립계좌 신청하기를 통해 신청 정보 동의 및 인적사항, 신청자료를 입력합니다.', 'https://www.artloan.kr/notice/savingsAccountProcess.do', '1. 주민등록초본
- 2026년 발급분
- 발급 시 발급대상자 본인 및 전체 발급

2. 소득금액증명원
- 2026년 발급분
- 귀속년도: 직전년도(2024년도) 소득금액증명원 발급
- 작성기준: 종합소득세 신고 현황의 소득금액(사업, 근로, 기타) 및 연말정산 현황의 근로소득, 사업소득의 소득금액 총합계 (소득이 없을경우, 사실증명원 제출 가능)

3. 성희롱·성폭력 예방교육 수료증
- 예술인권리보장시스템 (sinmungo.kawf.kr)에서 수강 후 수료증 발급

4. 출입국에 관한 사실증명
- 신청·접수 기간 내 발급
- 조회기간: 2024. 2. 4.부터 ~ 2026. 2. 3.까지', '4. 심사
접수하신 서류를 토대로 심사자가 심사를 진행합니다.

5. 승인 대상자 발표
심사를 거쳐 승인된 결과가 고객님께 문자메시지로 발송됩니다.
적립계좌 신청 내역은 마이페이지를 통해 확인 가능합니다.

6. 적금 계좌 개설
승인 후 지정 기간 내에 협력 은행의 비대면 계좌를 개설하여 적금에 가입합니다.

7. 예술활동 확인내역서 제출
24회차 내 총 4회간 예술활동 확인내역서를 제출하여야 합니다.

8. 총 24회차 납입
적립계좌를 개설한 청년예술인이 매달 적금 입금 시 지원금이 적립됩니다.

9. 만기 시 지원금 지급
※ 24개월 간 정상 납입한 회차에 비례하여 지원금을 지급합니다.', NULL, 'https://www.artloan.kr/notice/savingsAccount.do', NULL, '18', '39', 'N', '0055003', '0043002', '0', '3692', NULL, '「예술인복지법」상 예술활동증명을 완료한 예술인(신청일 기준 예술활동증명 유효자)
- 일반 예술활동증명 완료자(공개 발표된 예술활동, 예술활동 수입, 경력단절예술인, 특수한 작업방식, 무형유산 관련 특례), 신진예술인 예술활동증명 완료자
- 국내 거주 내국인 및 재외국민에 한함 (외국인은 참여 불가)
- 재외국민의 경우, 출입국사실증명을 통해 신청일 기준 2년간 국내 거주 사실이 확인되며 일시 출국 기간 매회 90일 이내 및 연간* 국내 체류 총합 183일 이상인 자
* 연간기준: (1차년) 2024. 2. 4. ~ 2025. 2. 3., (2차년) 2025. 2. 4. ~ 2026. 2. 3.', '1. 적금 7개월 이상 연속 미납자
2. 적금 만기 전 상품 해지자
3. 사망 및 압류계좌로 확인된 자
4. 적금 선납 시 1회 지원금만 지원되며, 잔여 회차 지원금 지급 불가(240만원 한도 외 추가 납입 불가)
* (예시) 적금 선납 예시
