INSERT INTO raw.welfare_service_detail ("servId", "servNm", "servDtlLink", "jurMnofNm", "tgtrDtlCn", "slctCritCn", "alwServCn", "wlfareInfoOutlCn", "crtrYr", "rprsCtadr", "sprtCycNm", "srvPvsnNm", "applmetList", "inqplCtadrList", "inqplHmpgReldList", "basfrmList", "baslawList", "source_url", "raw_data") VALUES ('WLF00000060', '청년내일저축계좌', 'https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00000060&wlfareInfoReldBztpCd=01', '보건복지부 자활정책과', '가입연령 : 신청 당시 만 15세~ 39세 ※ 신청 월의 전월에 만 15세가 된 자 ~ 신청 월에 만 40세가 되는 자근로·사업소득 : 근로,사업소득이 월10만원 이상 발생가구소득 : 소득인정액 기준 중위소득 50% 이하', '지원대상의 내용을 참고해주시기 바랍니다.', '매월 본인 저축 납입자에 한하여 본인저축액 10만원 이상(매월 전월 23일~현월 22일 입금마감일 이전) 대비 정부지원금을 정액 매칭합니다.중위소득 50%초과~100%이하 : 10만원 정액 매칭중위소득 50%이하 : 30만원 정액 매칭(3년간 통장유지, 근로활동 지속, 교육이수, 자금사용계획서 제출시 적립금 전액 지급)정책대상별 추가지원금(근로소득공제금(생계급여 수급 청년), 탈수급장려금, 내일키움장려금, 내일키움수익금 등) 지급이 가능합니다.', '근로빈곤층 청년의 생계수급자 등으로의 하락을 사전에 예방하고, 일하는 중간계층 청년이 사회에 안착할 수 있도록 자산형성을 지원합니다. (2026년 모집기간: ''26.5.4.(월) ~ ''26.5.20.(수))', '2026', '129', '월', '현금지급', '[{"servSeCode":"070","servSeDetailLink":"거주지 읍/면/동 주민센터, 주민센터 또는 복지로 웹사이트(PC/모바일앱)에서 ‘서비스 신청’","servSeDetailNm":"신청기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"거주지 읍/면/동 주민센터, 복지로(www.bokjiro.go.kr) 또는 복지로 웹사이트(PC/모바일앱)에서 ‘서비스 신청’","servSeDetailNm":"신청기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 주민센터에서 조사 및 심사","servSeDetailNm":"조사기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 시군구에서 보장 결정","servSeDetailNm":"결정기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 한국자활복지개발원에서 대상자에게 서비스 제공","servSeDetailNm":"지급기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 시군구에서 서비스 제공 이후 대상자의 상황 관리","servSeDetailNm":"사후관리기관목록"}]'::jsonb, '[{"servSeCode":"010","servSeDetailLink":"129","servSeDetailNm":"보건복지상담센터"},{"servSeCode":"010","servSeDetailLink":"1522-3690","servSeDetailNm":"자산형성지원 콜센터"}]'::jsonb, '[{"servSeCode":"020","servSeDetailLink":"http://www.129.go.kr","servSeDetailNm":"보건복지상담센터"},{"servSe