INSERT INTO raw.welfare_service_detail ("servId", "servNm", "servDtlLink", "jurMnofNm", "tgtrDtlCn", "slctCritCn", "alwServCn", "wlfareInfoOutlCn", "crtrYr", "rprsCtadr", "sprtCycNm", "srvPvsnNm", "applmetList", "inqplCtadrList", "inqplHmpgReldList", "basfrmList", "baslawList", "source_url", "raw_data") VALUES ('WLF00000100', '자산형성지원사업(희망저축계좌Ⅰ, Ⅱ)', 'https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00000100&wlfareInfoReldBztpCd=01', '보건복지부 자활정책과', '(희망저축계좌Ⅰ) 총 근로(사업)소득이 기준 중위소득 40%의 60% 이상인 생계·의료급여 수급 가구를 대상으로 합니다.(희망저축계좌Ⅱ) 가구 전체의 소득인정액이 기준 중위소득 50% 이하인 주거·교육급여 수급 가구 및 차상위 가구를 대상으로 합니다.', '희망저축계좌Ⅰ의 선정기준은 다음과 같습니다. (생계·의료 수급가구) 소득인정액이 기준중위소득 40% 이하인 가구 중(근로활동) 가구원 중 일하는 사람이 있어야 하며(소득기준) 신청 당시 가구 전체의 총 근로·사업소득(보장기관 확인 소득 제외)이 기준 중위소득 40%의 60% 이상인 가구희망저축계좌Ⅱ의 선정기준은 다음과 같습니다. (소득기준) 가구 전체의 소득인정액이 기준 중위소득 50% 이하인 주거·교육급여 수급 가구 및 기타 차상위 계층 가구(근로기준) 현재 근로활동 중이며 근로·사업소득이 있는 가구', '희망저축계좌Ⅰ은 본인 저축액 월 10만원 이상 저축 시(전월 전월 23일~현월 22일 입금마감일 이전) 정부지원금을 30만원을 매칭하여 지원합니다.※ 탈수급시 지원금 전액 지급※ 정책대상별 추가지원금(탈수급장려급, 내일키움장려금, 내일키움수익금 등) 추가 지급 가능희망저축계좌 Ⅱ는 본인 저축액 월 10만원* 이상 저축시(전월 23일~현월 22일 입금마감일 이전) 정부지원금 10만원을 매칭하여 지원합니다.* 정해진 교육(10시간) 이수 및 자금사용계획서 제출시 전액 지급 * 정책대상별 추가지원금(내일키움장려금, 내일키움수익금 등) 추가 지급 가능2025년 가입자부터 근로소득장려금 연차별 차등지원 적용(1년차 월 10만원 &rarr; 2년차 월 20만원 &rarr; 3년차 월 30만원)', '희망저축계좌를 통해 일하는 생계·의료·주거·교육급여 수급가구 및 차상위계층이 자활에 필요한 자산을 형성할 수 있도록 지원합니다.', '2026', '129', '월', '현금지급', '[{"servSeCode":"070","servSeDetailLink":"거주지 읍/면/동 주민센터, 읍면동 주민센터에서 ‘서비스 신청’","servSeDetailNm":"신청기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"거주지 읍/면/동 주민센터, 복지로(www.bokjiro.go.kr) 에서 ‘서비스 신청’","servSeDetailNm":"신청기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 시군구에서 조사 및 심사","servSeDetailNm":"조사기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 시군구에서 보장 결정","servSeDetailNm":"결정기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"이의가 있을 경우, 담당 시/군/구청 또는 시군구에 이의 신청 접수","servSeDetailNm":"이의신청접수기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 한국자활복지개발원에서 대상자에게 서비스 제공","servSeDetailNm":"지급기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 시군구에서 서비스 제공 이후 대상자의 상황 관리","servSeDetailNm":"사후관리기관목록"}]'::jsonb, '[{"servSeCode":"010","servSeDetailLink":"1522-3690","servSeDetailNm":"자산형성지원 콜센터"},{"servSeCode":"010","servSeDetailLink":"129","servSeDetailNm":"보건복지상담센터"}]'::jsonb, '[{"servSeCode":"020","servSeDetailLink":"https://hope.welfareinfo.or.kr","servSeDetailNm":"자산형성포털"},{"servSeCode":"020","servSeDetailLink":"http://www.129.go.kr","servSeDetailNm":"보건복지상담센터"}]'::jsonb, '{"servSeCode":"040","servSeDetailLink":"https://bokjiro.go.kr/ssis-tbu/CmmFileUtil/getDownload.do?atcflId=20260407TTWAT1353090010194108&atcflSn=1","servSeDetailNm":"2026년_자활사업안내(II)_자산형성지원통장사업_안내.pdf"}'::jsonb, '[{"servSeCode":"030","servSeDetailNm":"국민기초생활 보장법 시행령"},{"servSeCode":"030","servSeDetailNm":"국민기초생활 보장법"}]'::jsonb, 'https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00000100&wlfareInfoReldBztpCd=01', '{"servId":"WLF00000100","servNm":"자산형성지원사업(희망저축계좌Ⅰ, Ⅱ)","jurMnofNm":"보건복지부 자활정책과","tgtrDtlCn":"(희망저축계좌Ⅰ) 총 근로(사업)소득이 기준 중위소득 40%의 60% 이상인 생계·의료급여 수급 가구를 대상으로 합니다.\r(희망저축계좌Ⅱ) 가구 전체의 소득인정액이 기준 중위소득 50% 이하인 주거·교육급여 수급 가구 및 차상위 가구를 대상으로 합니다.","slctCritCn":"희망저축계좌Ⅰ의 선정기준은 다음과 같습니다. \r(생계·의료 수급가구) 소득인정액이 기준중위소득 40% 이하인 가구 중\r(근로활동) 가구원 중 일하는 사람이 있어야 하며\r(소득기준) 신청 당시 가구 전체의 총 근로·사업소득(보장기관 확인 소득 제외)이 기준 중위소득 40%의 60% 이상인 가구\r희망저축계좌Ⅱ의 선정기준은 다음과 같습니다. \r(소득기준) 가구 전체의 소득인정액이 기준 중위소득 50% 이하인 주거·교육급여 수급 가구 및 기타 차상위 계층 가구\r(근로기준) 현재 근로활동 중이며 근로·사업소득이 있는 가구","alwServCn":"희망저축계좌Ⅰ은 본인 저축액 월 10만원 이상 저축 시(전월 전월 23일~현월 22일 입금마감일 이전) 정부지원금을 30만원을 매칭하여 지원합니다.\r※ 탈수급시 지원금 전액 지급※ 정책대상별 추가지원금(탈수급장려급, 내일키움장려금, 내일키움수익금 등) 추가 지급 가능\r희망저축계좌 Ⅱ는 본인 저축액 월 10만원* 이상 저축시(전월 23일~현월 22일 입금마감일 이전) 정부지원금 10만원을 매칭하여 지원합니다.\r* 정해진 교육(10시간) 이수 및 자금사용계획서 제출시 전액 지급 * 정책대상별 추가지원금(내일키움장려금, 내일키움수익금 등) 추가 지급 가능\r2025년 가입자부터 근로소득장려금 연차별 차등지원 적용(1년차 월 10만원 &rarr; 2년차 월 20만원 &rarr; 3년차 월 30만원)","crtrYr":"2026","rprsCtadr":"129","wlfareInfoOutlCn":"희망저축계좌를 통해 일하는 생계·의료·주거·교육급여 수급가구 및 차상위계층이 자활에 필요한 자산을 형성할 수 있도록 지원합니다.","sprtCycNm":"월","srvPvsnNm":"현금지급","trgterIndvdlArray":"저소득","intrsThemaArray":"생활지원, 서민금융","applmetList":[{"servSeCode":"070","servSeDetailLink":"거주지 읍/면/동 주민센터, 읍면동 주민센터에서 ‘서비스 신청’","servSeDetailNm":"신청기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"거주지 읍/면/동 주민센터, 복지로(www.bokjiro.go.kr) 에서 ‘서비스 신청’","servSeDetailNm":"신청기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 시군구에서 조사 및 심사","servSeDetailNm":"조사기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 시군구에서 보장 결정","servSeDetailNm":"결정기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"이의가 있을 경우, 담당 시/군/구청 또는 시군구에 이의 신청 접수","servSeDetailNm":"이의신청접수기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 한국자활복지개발원에서 대상자에게 서비스 제공","servSeDetailNm":"지급기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 시군구에서 서비스 제공 이후 대상자의 상황 관리","servSeDetailNm":"사후관리기관목록"}],"inqplCtadrList":[{"servSeCode":"010","servSeDetailLink":"1522-3690","servSeDetailNm":"자산형성지원 콜센터"},{"servSeCode":"010","servSeDetailLink":"129","servSeDetailNm":"보건복지상담센터"}],"inqplHmpgReldList":[{"servSeCode":"020","servSeDetailLink":"https://hope.welfareinfo.or.kr","servSeDetailNm":"자산형성포털"},{"servSeCode":"020","servSeDetailLink":"http://www.129.go.kr","servSeDetailNm":"보건복지상담센터"}],"basfrmList":{"servSeCode":"040","servSeDetailLink":"https://bokjiro.go.kr/ssis-tbu/CmmFileUtil/getDownload.do?atcflId=20260407TTWAT1353090010194108&atcflSn=1","servSeDetailNm":"2026년_자활사업안내(II)_자산형성지원통장사업_안내.pdf"},"baslawList":[{"servSeCode":"030","servSeDetailNm":"국민기초생활 보장법 시행령"},{"servSeCode":"030","servSeDetailNm":"국민기초생활 보장법"}],"resultCode":"0","resultMessage":"SUCCESS"}'::jsonb) ON CONFLICT ("servId") DO UPDATE SET "servId" = EXCLUDED."servId", "servNm" = EXCLUDED."servNm", "servDtlLink" = EXCLUDED."servDtlLink", "jurMnofNm" = EXCLUDED."jurMnofNm", "tgtrDtlCn" = EXCLUDED."tgtrDtlCn", "slctCritCn" = EXCLUDED."slctCritCn", "alwServCn" = EXCLUDED."alwServCn", "wlfareInfoOutlCn" = EXCLUDED."wlfareInfoOutlCn", "crtrYr" = EXCLUDED."crtrYr", "rprsCtadr" = EXCLUDED."rprsCtadr", "sprtCycNm" = EXCLUDED."sprtCycNm", "srvPvsnNm" = EXCLUDED."srvPvsnNm", "applmetList" = EXCLUDED."applmetList", "inqplCtadrList" = EXCLUDED."inqplCtadrList", "inqplHmpgReldList" = EXCLUDED."inqplHmpgReldList", "basfrmList" = EXCLUDED."basfrmList", "baslawList" = EXCLUDED."baslawList", "source_url" = EXCLUDED."source_url", "raw_data" = EXCLUDED."raw_data";
INSERT INTO raw.welfare_service_detail ("servId", "servNm", "servDtlLink", "jurMnofNm", "tgtrDtlCn", "slctCritCn", "alwServCn", "wlfareInfoOutlCn", "crtrYr", "rprsCtadr", "sprtCycNm", "srvPvsnNm", "applmetList", "inqplCtadrList", "inqplHmpgReldList", "basfrmList", "baslawList", "source_url", "raw_data") VALUES ('WLF00006266', '청년미래적금', 'https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00006266&wlfareInfoReldBztpCd=01', '금융위원회 청년정책과', '아래 가입요건을 모두 충족하는 대한민국 거주 청년을 지원합니다.1. 나이요건 : 신규 가입일 기준 만 19세 ~ 34세 이하인 청년 (병역이행기간 최대 6년 추가 인정)2. 소득요건(일반형) 개인소득 7,500만원 이하 또는 연매출 3억원 이하 소상공인 중 가구 중위소득 200% 이하인 자(우대형) 개인소득 3,600만원 이하 중소기업 재직자 또는 연매출 1억원 이하 영세 소상공인 중 가구 중위소득 150% 이하인 자단, 비과세소득만 있는 경우는 제외하나, 육아휴직급여(육아휴직수당 포함) 또는 군장병급여만 있는 경우는 가입요건 소득에 포함일반형 소득요건 충족하는 중소기업 취업자는 우대형으로 분류3.  금융소득요건가입일이 속한 과세기간의 직전 3개 과세기간 중 1회 이상 금융소득종합과세대상*에 해당하지 않는 자* 이자소득 및 배당소득이 2천만원을 초과하는 자직전과세기간의 소득이 확정되기 이전에는 전전년도의 소득을 기준으로 산정함국세청의 소득확인증명서를 통해 소득확인이 이루어짐', '지원대상의 내용을 참고해주시기 바랍니다.', '은행이자에 더해 납입액의 일정비율로 정부기여금 지원 및 이자소득 비과세 혜택 제공', '청년의 중장기 자산형성 지원을 위한 정책형 금융상품으로, 만기 3년 동안 매월 50만원 한도 내에서 자유롭게 납입 가능한 정부지원형 적금 상품입니다. 2026년 6월 예정', '2026', '1397', '월', '기타', '[{"servSeCode":"070","servSeDetailLink":"거주지 읍/면/동 주민센터, 취급기관 모집 중에서 ‘서비스 신청’","servSeDetailNm":"신청기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 서민금융진흥원에서 조사 및 심사","servSeDetailNm":"조사기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 서민금융진흥원에서 보장 결정","servSeDetailNm":"결정기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 서민금융진흥원에서 대상자에게 서비스 제공","servSeDetailNm":"지급기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 서민금융진흥원에서 서비스 제공 이후 대상자의 상황 관리","servSeDetailNm":"사후관리기관목록"}]'::jsonb, '{"servSeCode":"010","servSeDetailLink":"1397(내선 3번)","servSeDetailNm":"서민금융진흥원"}'::jsonb, '[{"servSeCode":"020","servSeDetailLink":"https://www.kinfa.or.kr","servSeDetailNm":"서민금융진흥원"},{"servSeCode":"020","servSeDetailLink":"https://www.fsc.go.kr","servSeDetailNm":"금융위원회"}]'::jsonb, NULL, '{"servSeCode":"030","servSeDetailNm":"조세특례제한법"}'::jsonb, 'https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00006266&wlfareInfoReldBztpCd=01', '{"servId":"WLF00006266","servNm":"청년미래적금","jurMnofNm":"금융위원회 청년정책과","tgtrDtlCn":"아래 가입요건을 모두 충족하는 대한민국 거주 청년을 지원합니다.\r1. 나이요건 : 신규 가입일 기준 만 19세 ~ 34세 이하인 청년 (병역이행기간 최대 6년 추가 인정)\r2. 소득요건\r(일반형) 개인소득 7,500만원 이하 또는 연매출 3억원 이하 소상공인 중 가구 중위소득 200% 이하인 자\r(우대형) 개인소득 3,600만원 이하 중소기업 재직자 또는 연매출 1억원 이하 영세 소상공인 중 가구 중위소득 150% 이하인 자\r단, 비과세소득만 있는 경우는 제외하나, 육아휴직급여(육아휴직수당 포함) 또는 군장병급여만 있는 경우는 가입요건 소득에 포함\r일반형 소득요건 충족하는 중소기업 취업자는 우대형으로 분류\r3.  금융소득요건\r가입일이 속한 과세기간의 직전 3개 과세기간 중 1회 이상 금융소득종합과세대상*에 해당하지 않는 자\r* 이자소득 및 배당소득이 2천만원을 초과하는 자\r직전과세기간의 소득이 확정되기 이전에는 전전년도의 소득을 기준으로 산정함\r국세청의 소득확인증명서를 통해 소득확인이 이루어짐","slctCritCn":"지원대상의 내용을 참고해주시기 바랍니다.","alwServCn":"은행이자에 더해 납입액의 일정비율로 정부기여금 지원 및 이자소득 비과세 혜택 제공","crtrYr":"2026","rprsCtadr":"1397","wlfareInfoOutlCn":"청년의 중장기 자산형성 지원을 위한 정책형 금융상품으로, 만기 3년 동안 매월 50만원 한도 내에서 자유롭게 납입 가능한 정부지원형 적금 상품입니다. 2026년 6월 예정","sprtCycNm":"월","srvPvsnNm":"기타","lifeArray":"청년","intrsThemaArray":"서민금융, 생활지원","applmetList":[{"servSeCode":"070","servSeDetailLink":"거주지 읍/면/동 주민센터, 취급기관 모집 중에서 ‘서비스 신청’","servSeDetailNm":"신청기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 서민금융진흥원에서 조사 및 심사","servSeDetailNm":"조사기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 서민금융진흥원에서 보장 결정","servSeDetailNm":"결정기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 서민금융진흥원에서 대상자에게 서비스 제공","servSeDetailNm":"지급기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 서민금융진흥원에서 서비스 제공 이후 대상자의 상황 관리","servSeDetailNm":"사후관리기관목록"}],"inqplCtadrList":{"servSeCode":"010","servSeDetailLink":"1397(내선 3번)","servSeDetailNm":"서민금융진흥원"},"inqplHmpgReldList":[{"servSeCode":"020","servSeDetailLink":"https://www.kinfa.or.kr","servSeDetailNm":"서민금융진흥원"},{"servSeCode":"020","servSeDetailLink":"https://www.fsc.go.kr","servSeDetailNm":"금융위원회"}],"baslawList":{"servSeCode":"030","servSeDetailNm":"조세특례제한법"},"resultCode":"0","resultMessage":"SUCCESS"}'::jsonb) ON CONFLICT ("servId") DO UPDATE SET "servId" = EXCLUDED."servId", "servNm" = EXCLUDED."servNm", "servDtlLink" = EXCLUDED."servDtlLink", "jurMnofNm" = EXCLUDED."jurMnofNm", "tgtrDtlCn" = EXCLUDED."tgtrDtlCn", "slctCritCn" = EXCLUDED."slctCritCn", "alwServCn" = EXCLUDED."alwServCn", "wlfareInfoOutlCn" = EXCLUDED."wlfareInfoOutlCn", "crtrYr" = EXCLUDED."crtrYr", "rprsCtadr" = EXCLUDED."rprsCtadr", "sprtCycNm" = EXCLUDED."sprtCycNm", "srvPvsnNm" = EXCLUDED."srvPvsnNm", "applmetList" = EXCLUDED."applmetList", "inqplCtadrList" = EXCLUDED."inqplCtadrList", "inqplHmpgReldList" = EXCLUDED."inqplHmpgReldList", "basfrmList" = EXCLUDED."basfrmList", "baslawList" = EXCLUDED."baslawList", "source_url" = EXCLUDED."source_url", "raw_data" = EXCLUDED."raw_data";
INSERT INTO raw.welfare_service_detail ("servId", "servNm", "servDtlLink", "jurMnofNm", "tgtrDtlCn", "slctCritCn", "alwServCn", "wlfareInfoOutlCn", "crtrYr", "rprsCtadr", "sprtCycNm", "srvPvsnNm", "applmetList", "inqplCtadrList", "inqplHmpgReldList", "basfrmList", "baslawList", "source_url", "raw_data") VALUES ('WLF00001020', '북한이탈주민 자산형성지원제도(미래행복통장)', 'https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00001020&wlfareInfoReldBztpCd=01', '통일부 자립지원과', '2014년 11월 29일 이후 입국하여 보호결정을 받은 북향민 - 기존 거주지보호기간 5년 이내 가입 조건 폐지, 2025.2.11.부터 거주지보호기간이 경과된 북향민도 가입 가능3개월 이상 취업, 사업 등 경제 활동 상태가입신청일 기준 만 18세 이상', '미래행복통장 가입자격은 다음과 같습니다. 2014년 11월 29일 이후 입국하여 보호결정을 받은 상태인 자3개월 이상 취업/사업 등의 경제활동을 하고 있는 자(신청 당시 소득이 발생하고 있음을 의미함)가입 신청일 기준으로 만 18세 이상일 것다음에 해당하는 경우 가입대상에서 제외됩니다.가입 신청일 기준으로 전월의 소득이 국가데이터처가 발표하는 전년도 10분위별 근로자가구 가계수지의 9분위 소득 이상인 자정부ㆍ지방자치단체에서 시행중인 유사 사업(자산형성지원 사업)에 참여하여 지원을 받고 있거나 받았던 자「국가공무원」 및 「지방공무원법」에 따른 공무원「사립학교교직원 연금법」에 따른 교직원「별정우체국법」에 따른 직원「식품위생법 시행령」 제21조제8호에 따른 단란주점영업 및 유흥주점영업 사업장을 운영하거나 해당 사업장에 종사하고 있는 자「사행행위 등 규제 및 처벌특례법」 제2조제1항제2호에 따른 사행행위영업 사업장을 운영하거나 해당 사업장에 종사하고 있는 자취업한 사업장의 대표자가 미래행복통장 지원신청자와 배우자 또는 1촌 이내의 친족관계인 경우과거 약정상의 의무를 위반한 부정한 행위를 하여 미래행복통장 중도 해지가 된 자', '지원내용 : 본인 소득의 30% 범위 내, 월 10~50만원까지(5만원 단위) 1:1 매칭 적립지원기간 : 최대 4년(기본약정기간 2년 + 1년씩 최대 2년 연장)일시중지 및 중도해지 : 실직, 사고 등의 개인사유로 저축 일시중지 가능(최대 6회, 1년 6개월까지), ''출산, 병역, 장애, 학업'' 사유 발생 시 누적 일시 중지 기간을 포함하여 최대 2년간 일시 중지 가능, 자발적으로 해지하거나(중도해지) 약정을 위반하여 해지될 경우 본인적립금과 이자만 지급만기해지 : 약정기간 만료시까지 저축을 하고, 만기 지급 요건을 충족한 경우 본인적립금과 정부지원금(이자포함)을 지급가입자 의무사항 : 가입 기간 내 금융교육 필수 참여(1회 이상), 매월 재단과 약정한 적립금 적립 등', '북향민이 경제활동 소득 중 일정 금액을 저축하면 정부가 동일한 금액을 저축해 주는 사업으로, 북향민의 취업, 사업 등의 경제활동을 높여 우리 사회에 안정적으로 정착할 수 있도록 경제적 기반 마련을 지원합니다.', '2026', '02-3215-5792', '월', '현금지급', '[{"servSeCode":"070","servSeDetailLink":"거주지 읍/면/동 주민센터, 남북하나재단에서 ‘서비스 신청’","servSeDetailNm":"신청기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 남북하나재단에서 조사 및 심사","servSeDetailNm":"조사기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 남북하나재단에서 보장 결정","servSeDetailNm":"결정기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 남북하나재단에서 대상자에게 서비스 제공","servSeDetailNm":"지급기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 남북하나재단에서 서비스 제공 이후 대상자의 상황 관리","servSeDetailNm":"사후관리기관목록"}]'::jsonb, '[{"servSeCode":"010","servSeDetailLink":"02-3215-5792","servSeDetailNm":"남북하나재단"},{"servSeCode":"010","servSeDetailLink":"1577-6635","servSeDetailNm":"북한이탈주민 종합상담 콜센터"}]'::jsonb, '[{"servSeCode":"020","servSeDetailLink":"https://hanaportal.unikorea.go.kr","servSeDetailNm":"북한이탈주민 포털"},{"servSeCode":"020","servSeDetailLink":"https://www.koreahana.or.kr","servSeDetailNm":"남북하나재단"},{"servSeCode":"020","servSeDetailLink":"http://www.unikorea.go.kr","servSeDetailNm":"통일부"}]'::jsonb, NULL, '[{"servSeCode":"030","servSeDetailNm":"북한이탈주민의 보호 및 정착지원에 관한 법률"},{"servSeCode":"030","servSeDetailNm":"북한이탈주민의 보호 및 정착지원에 관한 법률 시행령"}]'::jsonb, 'https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00001020&wlfareInfoReldBztpCd=01', '{"servId":"WLF00001020","servNm":"북한이탈주민 자산형성지원제도(미래행복통장)","jurMnofNm":"통일부 자립지원과","tgtrDtlCn":"2014년 11월 29일 이후 입국하여 보호결정을 받은 북향민 - 기존 거주지보호기간 5년 이내 가입 조건 폐지, 2025.2.11.부터 거주지보호기간이 경과된 북향민도 가입 가능\r3개월 이상 취업, 사업 등 경제 활동 상태\r가입신청일 기준 만 18세 이상","slctCritCn":"미래행복통장 가입자격은 다음과 같습니다. \r2014년 11월 29일 이후 입국하여 보호결정을 받은 상태인 자\r3개월 이상 취업/사업 등의 경제활동을 하고 있는 자(신청 당시 소득이 발생하고 있음을 의미함)\r가입 신청일 기준으로 만 18세 이상일 것\r다음에 해당하는 경우 가입대상에서 제외됩니다.\r가입 신청일 기준으로 전월의 소득이 국가데이터처가 발표하는 전년도 10분위별 근로자가구 가계수지의 9분위 소득 이상인 자\r정부ㆍ지방자치단체에서 시행중인 유사 사업(자산형성지원 사업)에 참여하여 지원을 받고 있거나 받았던 자\r「국가공무원」 및 「지방공무원법」에 따른 공무원\r「사립학교교직원 연금법」에 따른 교직원\r「별정우체국법」에 따른 직원\r「식품위생법 시행령」 제21조제8호에 따른 단란주점영업 및 유흥주점영업 사업장을 운영하거나 해당 사업장에 종사하고 있는 자\r「사행행위 등 규제 및 처벌특례법」 제2조제1항제2호에 따른 사행행위영업 사업장을 운영하거나 해당 사업장에 종사하고 있는 자\r취업한 사업장의 대표자가 미래행복통장 지원신청자와 배우자 또는 1촌 이내의 친족관계인 경우\r과거 약정상의 의무를 위반한 부정한 행위를 하여 미래행복통장 중도 해지가 된 자","alwServCn":"지원내용 : 본인 소득의 30% 범위 내, 월 10~50만원까지(5만원 단위) 1:1 매칭 적립\r지원기간 : 최대 4년(기본약정기간 2년 + 1년씩 최대 2년 연장)\r일시중지 및 중도해지 : 실직, 사고 등의 개인사유로 저축 일시중지 가능(최대 6회, 1년 6개월까지), ''출산, 병역, 장애, 학업'' 사유 발생 시 누적 일시 중지 기간을 포함하여 최대 2년간 일시 중지 가능, 자발적으로 해지하거나(중도해지) 약정을 위반하여 해지될 경우 본인적립금과 이자만 지급\r만기해지 : 약정기간 만료시까지 저축을 하고, 만기 지급 요건을 충족한 경우 본인적립금과 정부지원금(이자포함)을 지급\r가입자 의무사항 : 가입 기간 내 금융교육 필수 참여(1회 이상), 매월 재단과 약정한 적립금 적립 등","crtrYr":"2026","rprsCtadr":"02-3215-5792","wlfareInfoOutlCn":"북향민이 경제활동 소득 중 일정 금액을 저축하면 정부가 동일한 금액을 저축해 주는 사업으로, 북향민의 취업, 사업 등의 경제활동을 높여 우리 사회에 안정적으로 정착할 수 있도록 경제적 기반 마련을 지원합니다.","sprtCycNm":"월","srvPvsnNm":"현금지급","lifeArray":"중장년, 청년","trgterIndvdlArray":"다문화·탈북민","intrsThemaArray":"서민금융, 생활지원","applmetList":[{"servSeCode":"070","servSeDetailLink":"거주지 읍/면/동 주민센터, 남북하나재단에서 ‘서비스 신청’","servSeDetailNm":"신청기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 남북하나재단에서 조사 및 심사","servSeDetailNm":"조사기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 남북하나재단에서 보장 결정","servSeDetailNm":"결정기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 남북하나재단에서 대상자에게 서비스 제공","servSeDetailNm":"지급기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 남북하나재단에서 서비스 제공 이후 대상자의 상황 관리","servSeDetailNm":"사후관리기관목록"}],"inqplCtadrList":[{"servSeCode":"010","servSeDetailLink":"02-3215-5792","servSeDetailNm":"남북하나재단"},{"servSeCode":"010","servSeDetailLink":"1577-6635","servSeDetailNm":"북한이탈주민 종합상담 콜센터"}],"inqplHmpgReldList":[{"servSeCode":"020","servSeDetailLink":"https://hanaportal.unikorea.go.kr","servSeDetailNm":"북한이탈주민 포털"},{"servSeCode":"020","servSeDetailLink":"https://www.koreahana.or.kr","servSeDetailNm":"남북하나재단"},{"servSeCode":"020","servSeDetailLink":"http://www.unikorea.go.kr","servSeDetailNm":"통일부"}],"baslawList":[{"servSeCode":"030","servSeDetailNm":"북한이탈주민의 보호 및 정착지원에 관한 법률"},{"servSeCode":"030","servSeDetailNm":"북한이탈주민의 보호 및 정착지원에 관한 법률 시행령"}],"resultCode":"0","resultMessage":"SUCCESS"}'::jsonb) ON CONFLICT ("servId") DO UPDATE SET "servId" = EXCLUDED."servId", "servNm" = EXCLUDED."servNm", "servDtlLink" = EXCLUDE