INSERT INTO raw.welfare_service_detail ("servId", "servNm", "servDtlLink", "jurMnofNm", "tgtrDtlCn", "slctCritCn", "alwServCn", "wlfareInfoOutlCn", "crtrYr", "rprsCtadr", "sprtCycNm", "srvPvsnNm", "applmetList", "inqplCtadrList", "inqplHmpgReldList", "basfrmList", "baslawList", "source_url", "raw_data") VALUES ('WLF00000023', '농어가목돈마련저축 저축장려금 지급', 'https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00000023&wlfareInfoReldBztpCd=01', '금융위원회 은행과', '농업인(임업인 포함), 어업인으로 「농어가목돈마련저축에 관한 법률 시행령」 제2조에 해당하는 사람을 대상으로 지원합니다.일반 농어민 - 건강보험료 납부금액이 금융위원회가 정하는 금액 이하인 농어민저소득 농어민 - 국민건강보험 미대상자인 농어민 (의료급여수급권자, 유공자등 의료보호대상자)  - 「국민건강보험법」상 피부양자인 농어민 - 건강보험료 납부금액이 금융위원회가 정하는 금액 이하인 농어민「농어가목돈마련저축에 관한 법률」 시행령 제2조 제3항에 따라 다음에 해당하는 사람은 가입대상에서 제외합니다.농어민으로서 종사하는 분야 외의 분야에서 상시 근로하고 있는 사람농어민으로서 종사하는 분야 외의 분야에서 직전 연도에 발생한 종합소득금액이 직전 연도 기준 중위소득의 100분의 40 이상인 사람', '지원대상의 내용을 참고해 주시기 바랍니다.', '농어가목돈마련저축 가입자에게 저축만기시 저축장려금을 지급합니다.만기해지 시 저축기관이 지급하는 기본이자 외 저축장려금 지급률(연이율)은 다음과 같습니다. 일반 농어민, 3년 : 0.9%일반 농어민, 5년 : 1.5%저소득농어민, 3년 : 3.0%저소득농어민, 5년 : 4.8%단, 중도해지할 경우에는 저축장려금 지급률이 달라질 수 있습니다.※ 「농어가목돈마련저축에 관한 법률」 시행령 제11조 참조', '농어가목돈마련저축 만기시 저축장려금을 지급하여 농어민의 재산 형성을 지원하고 저축 의욕을 높여 안정된 생활기반 조성에 기여합니다.', '2026', '1544-4200', NULL, NULL, '[{"servSeCode":"070","servSeDetailLink":"거주지 읍/면/동 주민센터, 관할 취급기관(농협, 축협, 수협 및 산림조합)에서 ‘서비스 신청’","servSeDetailNm":"신청기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 위탁 저축기관에서 조사 및 심사","servSeDetailNm":"조사기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 위탁 저축기관에서 보장 결정","servSeDetailNm":"결정기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 위탁 저축기관에서 대상자에게 서비스 제공","servSeDetailNm":"지급기관연락처목록"},{"servSeCode":"070","servSeDetailLink":"담당 시/군/구청 또는 위탁 저축기관에서 서비스 제공 이후 대상자의 상황 관리","servSeDetailNm":"사후관리기관목록"}]'::jsonb, '[{"servSeCode":"010","servSeDetailLink":"1661-2100","servSeDetailNm":"NH농협"},{"servSeCode":"010","servSeDetailLink":"1544-4200","servSeDetailNm":"산림조합"},{"servSeCode":"010","servSeDetai